function triangleRow(row: number): number[] {
  let prev = [1];
  for (let i = 1; i <= row; i++) {
    const cur = [1];
    for (let j = 1; j < i; j++) cur.push(prev[j - 1] + prev[j]);
    cur.push(1);
    prev = cur;
  }
  return prev;
}

